FLAC MIME Type Test FLAC MIME Type Test Current Server Configuration This test checks if the web server is correctly configured to serve FLAC files with the proper MIME type. Check Server Configuration FLAC MIME Type Check Testing if the server returns the correct MIME type (audio/flac) for FLAC files: Test File MIME Type Status Check MIME Types Audio Playback Test Standard Audio Element Your browser does not support the audio element. XMLHttpRequest Test Test XHR FLAC Loading Fetch API Test Test Fetch FLAC Loading Debug Log // Debug logger const log = document.getElementById('log'); function addLog(message, data = null) { const timestamp = new Date().toLocaleTimeString(); let formattedMessage = `[${timestamp}] ${message}`; if (data) { try { if (typeof data === 'object') { formattedMessage += '
' + JSON.stringify(data, null, 2); } else { formattedMessage += '
' + data; } } catch (e) { formattedMessage += '
[Unstringifiable data]'; } } log.innerHTML += formattedMessage + '

'; log.scrollTop = log.scrollHeight; console.log(message, data); } // Display result function showResult(element, message, type = 'info') { element.className = `result ${type}`; element.textContent = message; } // Check server configuration document.getElementById('check-config').addEventListener('click', function() { const configResult = document.getElementById('config-result'); // Check if running locally const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.hostname === ''; // Get server software if available fetch(window.location.origin, { method: 'HEAD' }) .then(response => { const server = response.headers.get('server'); const protocol = window.location.protocol; let configInfo = `Protocol: ${protocol}
`; configInfo += `Hostname: ${window.location.hostname}
`; configInfo += `Port: ${window.location.port || '(default)'}
`; configInfo += `Server: ${server || 'Unknown (not disclosed in headers)'}
`; configInfo += `Running locally: ${isLocalhost ? 'Yes' : 'No'}
`; // Check for web.config fetch('web.config', { method: 'HEAD' }) .then(webConfigResponse => { configInfo += `web.config accessible: ${webConfigResponse.ok ? 'Yes (WARNING: Should not be accessible!)' : 'No (Good)'}
`; if (isLocalhost) { configInfo += '
Recommendations for local testing:
'; configInfo += '- Ensure IIS or another web server is properly configured
'; configInfo += '- Verify MIME types are set in the web server configuration
'; configInfo += '- For IIS, check that web.config is properly loaded
'; } showResult(configResult, configInfo); }) .catch(error => { configInfo += `web.config check error: ${error.message}
`; showResult(configResult, configInfo); }); }) .catch(error => { showResult(configResult, `Error checking server configuration: ${error.message}`, 'error'); }); }); // Check MIME types for various audio files document.getElementById('check-mime').addEventListener('click', function() { const mimeResults = document.getElementById('mime-results'); mimeResults.innerHTML = ''; // Clear previous results // List of files to check const files = [ 'assets/audio/01. Hip-Hop Intro.flac', 'assets/audio/Jazz instrumental.flac', 'assets/audio/03.Mellow(1).flac' ]; files.forEach(file => { fetch(file, { method: 'HEAD' }) .then(response => { const mimeType = response.headers.get('content-type') || 'Not specified'; const isCorrect = mimeType.includes('audio/flac') || mimeType.includes('audio/x-flac'); addLog(`MIME type check for ${file}`, { mimeType, status: response.status, ok: response.ok }); const row = document.createElement('tr'); row.innerHTML = ` ${file} ${mimeType} ${isCorrect ? '✓ Correct' : '✗ Incorrect (should be audio/flac)'} `; mimeResults.appendChild(row); }) .catch(error => { addLog(`Error checking MIME type for ${file}`, error.message); const row = document.createElement('tr'); row.innerHTML = ` ${file} Error: ${error.message} `; mimeResults.appendChild(row); }); }); }); // Audio element tests const audioPlayer = document.getElementById('audio-player'); const audioStatus = document.getElementById('audio-status'); // Track audio events audioPlayer.addEventListener('loadstart', () => { audioStatus.innerHTML = ' Loading started... '; addLog('Audio: Loading started'); }); audioPlayer.addEventListener('canplay', () => { audioStatus.innerHTML = ' Audio can be played! '; addLog('Audio: Can play'); }); audioPlayer.addEventListener('error', () => { const error = audioPlayer.error; let errorMessage = 'Unknown error'; if (error) { switch(error.code) { case MediaError.MEDIA_ERR_ABORTED: errorMessage = 'Playback aborted by the user'; break; case MediaError.MEDIA_ERR_NETWORK: errorMessage = 'Network error while loading the audio file'; break; case MediaError.MEDIA_ERR_DECODE: errorMessage = 'Audio decoding error - the browser cannot decode this file format'; break; case MediaError.MEDIA_ERR_SRC_NOT_SUPPORTED: errorMessage = 'The audio file format or MIME type is not supported by the browser'; break; } } audioStatus.innerHTML = ` Error: ${errorMessage} `; addLog('Audio error', { code: error ? error.code : 'unknown', message: errorMessage }); }); // XHR test document.getElementById('xhr-test').addEventListener('click', function() { const xhrResult = document.getElementById('xhr-result'); const audioFile = 'assets/audio/01. Hip-Hop Intro.flac'; addLog('Starting XHR test for', audioFile); showResult(xhrResult, 'Testing FLAC loading using XMLHttpRequest...'); const xhr = new XMLHttpRequest(); xhr.open('GET', audioFile); // We want the raw binary data xhr.responseType = 'arraybuffer'; xhr.onload = function() { if (xhr.status === 200) { const arrayBuffer = xhr.response; const byteArray = new Uint8Array(arrayBuffer); // Check for FLAC signature (first 4 bytes should be "fLaC") const signature = String.fromCharCode(byteArray[0], byteArray[1], byteArray[2], byteArray[3]); const isFlac = signature === 'fLaC'; const fileInfo = { size: byteArray.length, mimeType: xhr.getResponseHeader('content-type'), signature: signature, isValidFlac: isFlac }; addLog('XHR loaded successfully', fileInfo); if (isFlac) { showResult(xhrResult, `Successfully loaded FLAC file (${(byteArray.length/1024/1024).toFixed(2)} MB)
MIME Type: ${fileInfo.mimeType}
Signature: "${signature}" (Valid FLAC)`, 'success'); } else { showResult(xhrResult, `Loaded file but it does not appear to be a valid FLAC file
MIME Type: ${fileInfo.mimeType}
Signature: "${signature}" (Expected "fLaC")`, 'warning'); } } }; xhr.onerror = function() { addLog('XHR error', xhr.statusText); showResult(xhrResult, `Error loading file: ${xhr.statusText}`, 'error'); }; xhr.onprogress = function(event) { if (event.lengthComputable) { const percentComplete = (event.loaded / event.total) * 100; showResult(xhrResult, `Loading: ${percentComplete.toFixed(1)}%`); } }; xhr.send(); }); // Fetch API test document.getElementById('fetch-test').addEventListener('click', function() { const fetchResult = document.getElementById('fetch-result'); const audioFile = 'assets/audio/01. Hip-Hop Intro.flac'; addLog('Starting Fetch test for', audioFile); showResult(fetchResult, 'Testing FLAC loading using Fetch API...');
